effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    float t = floor(acTime*speed*6.0);
    vec2 uv = acScreenNorm;
    float col = floor(uv.x/size);
    float r = rand(vec2(col, t));
    float sh = step(1.0-amount*0.7, r) * (rand(vec2(col*1.7, t))-0.5)*0.4;
    uv.y = fract(uv.y + sh);
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
